import React from 'react';

function JobList({ jobs }) {
  return (
    <div>
      <h2>Job List</h2>
      <p>Below is the list of jobs added. Each entry shows the job title, company, salary in USD, and sector.</p>
      <ul>
        {jobs.length === 0 ? (
          <li>No jobs available. Please add a job using the form above.</li>
        ) : (
          jobs.map((job) => (
            <li key={job.id}>
              <strong>{job.title}</strong> at {job.company} - ${job.salary.toLocaleString()} ({job.sector})
            </li>
          ))
        )}
      </ul>
    </div>
  );
}

export default JobList;
